    expect(validateMessage({type: 'list_sessions'})).toEqual({valid: true, data: {type: 'list_sessions'}});
  });

  it('accepts list_sessions, forwarding only a valid limit and before cursor', () => {
    const before = {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 's1'};

    expect(validateMessage({type: 'list_sessions', limit: 10, before, userId: 'u2'})).toEqual({
      valid: true,
      data: {type: 'list_sessions', limit: 10, before},
    });
  });

  it.each([
    {limit: 'ten'},
    {limit: -1},
    {limit: 1.5},
    {before: 'not-an-object'},
    {before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: ''}},
    {before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 'a'.repeat(129)}},
    {before: {updatedAt: 'not-a-date', sessionId: 's1'}},
    {before: {updatedAt: true, sessionId: 's1'}},
  ])('rejects a list_sessions frame with %j', fields => {
    const result = validateMessage({type: 'list_sessions', ...fields});

    expect(result.valid).toBe(false);
  });
});

